37: Vector2D PathFinding::GetNextWaypoint(const Vector2D& currentPos, const Waypoint& target) const
38: {
39:     // Calculate direction to target
40:     float dx = target.x - currentPos.x;
41:     float dy = target.y - currentPos.y;
42:     float distance = sqrtf(dx * dx + dy * dy);
43:     
44:     if (distance == 0.0f)
45:         return currentPos;
46:     
47:     // Normalize and scale to movement step
48:     const float STEP_SIZE = 10.0f;
49:     float step = std::min(STEP_SIZE, distance);
50:     
51:     Vector2D nextPos;
52:     nextPos.x = currentPos.x + (dx / distance) * step;
53:     nextPos.y = currentPos.y + (dy / distance) * step;
54:     
55:     return nextPos;
56: }
