78: std::vector<Vector2D> PathFinding::FindPath(const Vector2D& start, const Vector2D& end,
79:                                             const std::vector<MobInfo>& obstacles) const
80: {
81:     std::vector<Vector2D> path;
82:     path.push_back(start);
83:     
84:     // Simple pathfinding: move towards target with mob avoidance
85:     const float GRID_SIZE = 20.0f;
86:     const float GRID_CHECK = 30.0f;
87:     
88:     Vector2D current = start;
89:     
90:     while (Distance(current, end) > GRID_SIZE)
91:     {
92:         // Calculate direction to target
93:         float dx = end.x - current.x;
94:         float dy = end.y - current.y;
95:         float distance = sqrtf(dx * dx + dy * dy);
96:         
97:         if (distance == 0.0f)
98:             break;
99:         
100:         // Normalize
101:         float ndx = dx / distance;
102:         float ndy = dy / distance;
103:         
104:         // Check if we can move directly
105:         Vector2D directNext;
106:         directNext.x = current.x + ndx * GRID_CHECK;
107:         directNext.y = current.y + ndy * GRID_CHECK;
108:         
109:         if (IsWalkable(directNext, obstacles))
110:         {
111:             current = directNext;
112:             path.push_back(current);
113:         }
114:         else
115:         {
116:             // Try perpendicular directions (mob avoidance)
117:             Vector2D leftNext;
118:             leftNext.x = current.x + (-ndy) * GRID_CHECK;
119:             leftNext.y = current.y + ndx * GRID_CHECK;
120:             
121:             Vector2D rightNext;
122:             rightNext.x = current.x + ndy * GRID_CHECK;
123:             rightNext.y = current.y + (-ndx) * GRID_CHECK;
124:             
125:             if (IsWalkable(leftNext, obstacles))
126:             {
127:                 current = leftNext;
128:                 path.push_back(current);
129:             }
130:             else if (IsWalkable(rightNext, obstacles))
131:             {
132:                 current = rightNext;
133:                 path.push_back(current);
134:             }
135:             else
136:             {
137:                 // Back off and try again
138:                 current.x -= ndx * GRID_SIZE;
139:                 current.y -= ndy * GRID_SIZE;
140:             }
141:         }
142:         
143:         // Safety check to prevent infinite loops
144:         if (path.size() > 500)
145:             break;
146:     }
147:     
148:     path.push_back(end);
149:     return path;
150: }

